pub fn spawn_detached_handoff(command: &mut std::process::Command, label: &str) -> Result<DetachedProcessHandoff, String> {
    #[cfg(unix)] {
        use std::os::unix::process::CommandExt;
        command.process_group(0);
    }
    let child = match command.spawn() {
        Ok(child) => child,
        Err(error) => {
            let text = format!("spawn detached process: {error}");
            emit_process_error_receipt(command, label, 0, &text);
            return Err(text);
        }
    };
    let pid = child.id();
    let (cwd, program, env_names) = process_receipt_command_fields(command);
    println!("eoie process-handoff receipt label={label} stage=spawned pid={pid} child_exit=pending signal=pending timeout=0 retryability=unknown cwd={cwd:?} program={program:?} env_names={env_names}");
    Ok(DetachedProcessHandoff { pid, cwd, program, env_names })
}



